func:
// Checks the request of the lake API (GET ?path=<file> or ?list=<folder>).
// In: msg.req.query.path = a .parquet file, or query.list = a folder.
// Out 1: msg.mode, msg.folder and msg.key for the list step.
// Out 2: a 400 answer. It also gives the log lanes the root folder.
var REQUIRED_ENDING = '.parquet';

var query = (msg.req && msg.req.query) || {};
var path = String(query.path || '');
var list = String(query.list || '');
var target = path || list;

var problem = '';
if (path && list) {
  problem = 'use path or list, not both';
} else if (!target) {
  problem = 'query parameter path or list is missing';
} else if (target.indexOf('..') !== -1 || target.indexOf('\\') !== -1) {
  problem = 'the path must not contain .. or a backslash';
} else if (target.charAt(0) === '/') {
  problem = 'the path must not start with /';
} else if (path && path.slice(-REQUIRED_ENDING.length) !== REQUIRED_ENDING) {
  problem = 'only ' + REQUIRED_ENDING + ' files can be requested';
} else if (list && list.slice(-1) !== '/') {
  problem = 'a folder must end with /';
}

// The log lanes read the root folder of the data lake from here.
var shared = glob.get('cfg');
if (shared && shared.root) {
  flow.set('cfg', {
    root: shared.root
  });
}

if (problem) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: problem
  });
  msg.statusCode = 400;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: problem
  };
  return [null, msg];
}

msg.mode = path ? 'file' : 'list';
msg.key = path;
msg.folder = list || path.slice(0, path.lastIndexOf('/') + 1);
msg.path = msg.folder;
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.mode + ' ' + target
});
return [msg, null];

// Decides what to do with the result of the list objects node.
// In: msg.payload = the objects of the folder, msg.mode (file or list).
// Out 1: file found, msg.path = the file for the read node.
// Out 2: the answer: the folder list as JSON, or 404 for a missing file.
var items = Array.isArray(msg.payload) ? msg.payload : [];

msg.headers = {
  'content-type': 'application/json'
};

if (msg.mode === 'list') {
  msg.statusCode = 200;
  msg.size = items.length;
  msg.payload = {
    folder: msg.folder,
    count: items.length,
    objects: items.map(function (item) {
      return {
        key: item.key,
        last_modified: item.lastModified,
        size: item.contentSize
      };
    })
  };
  return [null, msg];
}

var found = items.filter(function (item) {
  return item.key === msg.key;
})[0];

if (!found) {
  node.status({
    fill: 'yellow',
    shape: 'ring',
    text: 'not found, ' + items.length + ' listed'
  });
  msg.statusCode = 404;
  msg.payload = {
    error: 'file not found',
    path: msg.key,
    listed_in_folder: items.length
  };
  return [null, msg];
}

msg.path = found.key;
msg.size = found.contentSize;
return [msg, null];

// Turns the read result into the HTTP answer with the parquet file.
// In: msg.payload = file content (Buffer or serialised Buffer).
// Out: the file as bytes. 502 if the bytes do not start with PAR1.
// Header x-parquet-magic tells if the first 4 bytes are PAR1.
var MAGIC = 'PAR1';

var content = msg.payload;
var bytes = null;
if (Buffer.isBuffer(content)) {
  bytes = content;
} else if (content && content.type === 'Buffer' && content.data) {
  bytes = Buffer.from(content.data);
}

var magic = false;
if (bytes) {
  magic = bytes.slice(0, 4).toString('latin1') === MAGIC;
}

if (!magic) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'not a parquet file'
  });
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the data lake did not return a parquet file',
    path: msg.path
  };
  return msg;
}

var name = String(msg.path).split('/').pop();
node.status({
  fill: 'green',
  shape: 'dot',
  text: bytes.length + ' bytes'
});
msg.statusCode = 200;
msg.size = bytes.length;
msg.headers = {
  'content-type': 'application/octet-stream',
  'content-disposition': 'attachment; filename="' + name + '"',
  'x-parquet-magic': 'ok',
  'x-file-size': String(bytes.length)
};
msg.payload = bytes;
return msg;

// Logs one line per request and passes the answer on.
// In: the answer message (msg.statusCode, msg.mode, msg.key or msg.folder).
// Out 1: the answer for the http response node.
// Out 2: one log line. The key of the endpoint is never logged.
var MAX_TEXT = 200;

var query = (msg.req && msg.req.query) || {};
var status = msg.statusCode || 200;
var what = String(query.path || query.list || '').slice(0, MAX_TEXT);
var kind = query.list ? 'list' : 'file';

var text = 'GET ' + kind + ' ' + what + ' -> ' + status;
if (msg.size !== undefined) {
  text += ' (' + msg.size + (kind === 'list' ? ' objects)' : ' bytes)');
}

var level = 'info';
if (status >= 500) {
  level = 'failed';
} else if (status >= 400) {
  level = 'warn';
}

var line = {
  payload: text,
  level: level,
  source: 'lake-api'
};
return [msg, line];

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'lake-api';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'lake-api';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
